class Solution:
    def networkDelayTime(self, times, n, k):
        INF = 10**18
        dist = [INF] * (n + 1)
        dist[k] = 0

        for _ in range(n - 1):
            changed = False
            for u, v, w in times:
                if dist[u] != INF and dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
                    changed = True
            if not changed:
                break

        answer = max(dist[1:])
        return -1 if answer == INF else answer

